FROM (SELECT business_date, hierarchy_level, account, portfolio_type, department, strategy, program, sub_program, analytic_value, tenor, curve_type, analytic_name, analytic_type, node_level,rating,currency,node
FROM "risk_prod"."rmv_analytics"
WHERE analytic_type IN ('DV01', 'PV', 'CS01', 'VOLATILITY_10YR','VAR_10YR')
  AND portfolio_type IN ('TOTAL_FUND_BY_ACCOUNT', 'IP')
  and (confidence_level is null or confidence_level = 0.95)
  AND (
    (analytic_type IN ('PV', 'VOLATILITY_10YR','VAR_10YR') AND hierarchy_level IN ('CPPIB-ALL', 'DEPARTMENT', 'ACCOUNT', 'POOL', 'STRATEGY', 'PROGRAM', 'SUB-PROGRAM'))
    OR (analytic_type IN ('CS01', 'DV01') AND hierarchy_level = 'MODEL_PORTFOLIO')
  )) AS "New custom SQL"
WHERE "department" IN ('Total Fund Management') AND date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) = date_trunc('day', CAST(CAST(PARSE_DATETIME('2025-06-19 00:00:00', 'yyyy-MM-dd HH:mm:ss') AS TIMESTAMP) AS TIMESTAMP)) AND CASE WHEN "account" IS NULL AND "portfolio_type" = 'IP' THEN 'TOTAL FUND' ELSE "account" END IN ('TOTAL FUND') AND "analytic_type" IN ('VOLATILITY_10YR', 'PV') AND "hierarchy_level" = 'DEPARTMENT'
GROUP BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP))
ORDER BY date_trunc('day', CAST(CAST(PARSE_DATETIME("business_date", 'yyyy-MM-dd') AS TIMESTAMP) AS TIMESTAMP)) DESC
LIMIT 2

/* cppi::50892fa8292836b3419abdf5232652954f837c9dea4123c14c9e5662706faab8 */
select business_date, index_id, currency_code, market_value_base, weight, arrival_time
from (
        select *, max(arrival_time) over (partition by index_id, currency_code, business_date) max_publish
            from performance.production_sa_index_mix_by_currency
            where business_date between date '1989-07-31' and date '2025-04-01'
            and to_date(substring(cast(arrival_time as varchar), 1, 8), 'yyyymmdd') <= date '2025-04-01'
    ) a
where arrival_time = max_publish

